function b64decode(str) {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  let s = (str || '').replace(/-/g, '+').replace(/_/g, '/').replace(/[^A-Za-z0-9+/=]/g, '');
  while (s.length % 4) s += '=';
  let out = '';
  let bits = 0, val = 0;
  for (const ch of s) {
    if (ch === '=') break;
    const idx = chars.indexOf(ch);
    if (idx < 0) continue;
    val = (val << 6) | idx; bits += 6;
    if (bits >= 8) { bits -= 8; out += String.fromCharCode((val >> bits) & 0xff); }
  }
  try { return decodeURIComponent(escape(out)); } catch (e) { return out; }
}
function bodyFromParts(parts) {
  let text = '';
  for (const part of parts || []) {
    if (part.mimeType === 'text/plain' && part.body && part.body.data) {
      text += b64decode(part.body.data) + '\n';
    } else if (Array.isArray(part.parts)) {
      text += bodyFromParts(part.parts);
    }
  }
  return text;
}
const items = [];
for (const item of $input.all()) {
  const j = item.json || {};
  const headers = {};
  if (j.payload && Array.isArray(j.payload.headers)) {
    for (const h of j.payload.headers) headers[(h.name || '').toLowerCase()] = h.value || '';
  }
  const messageId = (j.id || j.messageId || '').toString().trim();
  let from = headers['from'] || '';
  if (!from && j.from) {
    if (typeof j.from === 'string') from = j.from;
    else if (j.from.value && j.from.value[0]) from = j.from.value[0].address || j.from.value[0].name || '';
    else from = j.from.address || j.from.name || '';
  }
  from = from.toString().trim();
  const subject = (headers['subject'] || j.subject || '').toString().trim();
  let body = '';
  if (typeof j.text === 'string' && j.text.trim()) body = j.text;
  else if (j.payload) body = bodyFromParts(j.payload.parts) || (j.payload.body && j.payload.body.data ? b64decode(j.payload.body.data) : '');
  if (!body.trim() && j.snippet) body = j.snippet;
  body = body.toString().trim();
  const reasons = [];
  if (!messageId) reasons.push('missing message ID');
  if (!from) reasons.push('missing sender');
  items.push({ json: {
    messageId, from, subject, body,
    receivedAt: new Date().toISOString(),
    valid: reasons.length === 0,
    invalid_reason: reasons.join('; ')
  }});
}
return items;

