const mail = $('Build Classify Prompt').first().json;
const resp = $input.first().json;
const base = {
  receivedAt: mail.receivedAt, messageId: mail.messageId, from: mail.from,
  subject: mail.subject, body: mail.body
};
function needsReview(why) {
  return [{ json: { ...base, category: '', summary: '',
    reason: 'Needs review - ' + why,
    next_action: 'Open the email and triage it by hand',
    ai_ok: false, status: 'Needs Review', ai_error: why,
    label_applied: false, draft_status: '', draft_id: '' } }];
}
let text = '';
try {
  text = resp.candidates[0].content.parts.map(p => p.text || '').join('');
} catch (e) { return needsReview('AI response had no readable text'); }
text = text.trim().replace(/^```(?:json)?\s*/i, '').replace(/\s*```$/, '');
let aiObj = null;
try { aiObj = JSON.parse(text); } catch (e) { return needsReview('AI output was not valid JSON'); }
if (!aiObj || typeof aiObj !== 'object' || Array.isArray(aiObj)) return needsReview('AI output was not a JSON object');
const category = (aiObj.category === undefined || aiObj.category === null) ? '' : aiObj.category.toString().trim().toUpperCase();
if (!['URGENT', 'NEEDS_REPLY', 'FYI', 'PROMO'].includes(category)) return needsReview('AI category missing or not one of URGENT/NEEDS_REPLY/FYI/PROMO');
if (typeof aiObj.summary !== 'string' || !aiObj.summary.trim()) return needsReview('AI summary missing or empty');
return [{ json: { ...base, category,
  summary: aiObj.summary.trim().slice(0, 300),
  reason: '', next_action: '',
  ai_ok: true, status: 'Processed', ai_error: '',
  label_applied: false, draft_status: '', draft_id: '' } }];

